function threeSum(arr, target) {
  arr.sort((a, b) => a - b);

  for (let i = 0; i < arr.length - 2; i++) {
    let left = i + 1;
    let right = arr.length - 1;

    while (left < right) {
      const sum = arr[i] + arr[left] + arr[right];

      if (sum === target) {
        return [i, left, right];
      }

      if (sum < target) {
        left++;
      } else {
        right--;
      }
    }
  }

  return [];
}

Time: O(n²)
Space: O(1) (excluding sorting implementation)

Why: Sort once, then for each i, use two pointers instead of checking every j/k combination.

Note: If you need the original indices after sorting, the approach needs a small modification.

