function isValid(text) {
    const stack = [];
    const pairs = {
        ')': '(',
        '}': '{',
        ']': '['
    };

    for (const char of text) {
        if (char === '(' || char === '{' || char === '[') {
            stack.push(char);
        } else {
            if (stack.length === 0) {
                return false;
            }
            const lastElement = stack.pop(); // remove last and return last
            if (lastElement !== pairs[char]) {
                return false;
            }
        }
    }
    return stack.length === 0;
}

