function deleteNthNodeFromEnd(head, n) {
  const dummy = new Node(0);
  dummy.next = head;

  let slow = dummy;
  let fast = dummy;

  // Move fast n steps ahead
  for (let i = 0; i < n; i++) {
    fast = fast.next;
  }

  // Move both until fast reaches the end
  while (fast.next !== null) {
    slow = slow.next;
    fast = fast.next;
  }

  // Remove target node
  slow.next = slow.next.next;

  return dummy.next;
}

